/* common.mpvo.selectMasterMpVoVocDeptSearchPop */ SELECT X.COMPANY_CODE, Y.COM_NAME_LOC, X.CODE, X.TEXT1 FROM V_VOC_ICOMCOD2 X , V_VOC_ICOMCMPY Y WHERE X.TYPE = 'C001' AND X.SYS_TYPE = Y.SYS_TYPE AND X.COMPANY_CODE = Y.COM_CODE AND X.SYS_TYPE = 'SA' AND Y.COM_TYPE = 'PB' AND Y.STATUS <> 'D'
AND X.COMPANY_CODE = #{com_code}
AND UPPER(X.TEXT1) LIKE UPPER('%' || #{st_req_dept_name} || '%')
ORDER BY X.COMPANY_CODE, X.TEXT1
